def build():
    result = []
    forms = {'двор': 'дворе', 'бассейн': 'бассейне', 'карандаш': 'карандашом', 'покупка': 'покупка',
             'вокзал': 'вокзале', 'пересадка': 'пересадкой', 'температура': 'температуру',
             'анализ': 'анализа', 'удобный': 'удобное', 'политика': 'политику'}
    for name, stage, title, turns, lines in SPECS:
        targets = []
        for i, line in enumerate(lines.strip().splitlines(), 1):
            term, hint, form, meaning, distractors, review = line.split('|')
            targets.append(dict(id=f'{name}_{i}', term=term, sense_hints=[hint], target=form,
                                meaning=meaning, distractors=distractors.split(';'), review_text=review,
                                review_target=forms.get(term, form)))
        result.append(dict(id='vocab_' + name, stage=stage, title=title, language='ru',
                           turns=[dict(speaker=s, text=t) for s, t in turns], targets=targets,
                           review_status='provisional', authoring='Original fictional study material; not official test content'))
    return dict(version=1, passages=result)


if __name__ == '__main__':
    data = build()
    path = ROOT / 'data/study/passages.json'
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
    print(f"{len(data['passages'])} passages; {sum(len(t['text']) for p in data['passages'] for t in p['turns'])} input characters")
